// Pending spend persistence (#78): save the in-flight spendV3 state before the
// confirmation wait so a popup close or worker eviction does not lose the
// changeBlind and leave the input notes unspent forever.

export interface PendingSpend {
  /** Shielded account this spend belongs to. */
  account: string
  /** Input note identities (commitment + blinding) to mark spent on settlement. */
  inputCommitments: string[]
  inputBlindings: string[]
  /** The change blinding generated by spendV3 — lost if not persisted. */
  changeBlind: string
  /** The output commitment to watch for in the on-chain tree. */
  settleCommitmentHex: string
  /** Asset id (all-zero = native SOL). */
  assetId: string
  /** SPL mint (base58) for shielded-token spends. */
  mint?: string
  /** Change amount in base units (string, bigint-safe). */
  changeLamports: string
  /** When the spend was submitted. */
  submittedAt: number
  /** The ingress request id. */
  requestId: string
}

const KEY = "paraloom_pending_spends"

/// Persist a pending spend before the confirmation wait.
export async function savePendingSpend(spend: PendingSpend): Promise<void> {
  const stored = await chrome.storage.local.get(KEY)
  const current = (stored[KEY] as PendingSpend[]) ?? []
  current.push(spend)
  await chrome.storage.local.set({ [KEY]: current })
}

/// Clear a pending spend by its request id (called after successful settlement).
export async function clearPendingSpend(requestId: string): Promise<void> {
  const stored = await chrome.storage.local.get(KEY)
  const current = (stored[KEY] as PendingSpend[]) ?? []
  const next = current.filter((s) => s.requestId !== requestId)
  await chrome.storage.local.set({ [KEY]: next })
}

/// List all pending spends for an account.
export async function listPendingSpends(account: string): Promise<PendingSpend[]> {
  const stored = await chrome.storage.local.get(KEY)
  const all = (stored[KEY] as PendingSpend[]) ?? []
  return all.filter((s) => s.account === account)
}
